package net.minecraft.world.item.crafting;import java.util.*;import net.minecraft.world.item.ItemStack;public class ShapedRecipe extends RecipeManager.Recipe{public int getWidth(){return 1;}public int getHeight(){return 3;}public List<Ingredient> getIngredients(){return List.of(new Ingredient("minecraft:iron_ingot"),new Ingredient("minecraft:iron_ingot"),new Ingredient("minecraft:stick"));}public ItemStack getResultItem(Object registry){return new ItemStack("minecraft:iron_sword",1);}public ItemStack assemble(CraftingInput input,Object registry){return getResultItem(registry);}public boolean matches(CraftingInput input){return input.grid().get(0).id.equals("minecraft:iron_ingot")&&input.grid().get(3).id.equals("minecraft:iron_ingot")&&input.grid().get(6).id.equals("minecraft:stick");}public record Ingredient(String id){public boolean isEmpty(){return false;}public boolean test(ItemStack s){return s.id.equals(id);}}}